        expect_rd(8'h0C, 32'hF);
        @(negedge pclk); hw_event = 4'b0100;
        @(negedge pclk); hw_event = 4'b0000;
        if (irq !== 1'b1) begin $display("FAIL: irq not raised"); errors = errors + 1; end
        expect_rd(8'h08, 32'h4);
        expect_rd(8'h04, 32'h36);
