                errors = errors + 1;
            end
            @(negedge clk);
            if (done !== 1'b0) begin $display("FAIL: done longer than one cycle"); errors = errors + 1; end
        end
    endtask

    initial begin
        #1 rst_n = 0;
        #11 rst_n = 1;
