        end
        @(negedge clk); out_ready = 1;
        @(posedge clk); #1; expect_out(0, 8'h00);
        if (errors == 0) $display("TEST PASSED");
        else $display("TEST FAILED: %0d errors", errors);
        $finish;
    end
endmodule

