        #1 rst_n = 0;
        #11 rst_n = 1;
        read_check(3'd3, 8'h00, 3'd5, 8'h00);
        for (i = 1; i < 8; i = i + 1) write(i, 8'h10 * i + i);
        for (i = 1; i < 8; i = i + 1) read_check(i, 8'h10 * i + i, 8 - i, 8'h10 * (8 - i) + (8 - i));
