module tb_scratch;
    reg  [12:0] cw;
    wire [7:0]  data;
    wire        single_err, double_err;
    wire [3:0]  err_pos;

    hamming_secded dut (.cw(cw), .data(data), .single_err(single_err),
                        .double_err(double_err), .err_pos(err_pos));

