                        cw[1]^cw[3]^cw[5]^cw[7]^cw[9]^cw[11]};
            par_calc = ^cw;
            if (par_calc && syn_calc > 12) begin
                if (!(double_err && !single_err && err_pos == 0))
                    $display("FAIL syn13-15 case: cw=%h syn=%0d single=%b double=%b pos=%0d",
                              cw, syn_calc, single_err, double_err, err_pos);
