                if (data !== {cw[12],cw[11],cw[10],cw[9],cw[7],cw[6],cw[5],cw[3]})
                    $display("FAIL double-err data not raw: cw=%h syn=%0d data=%h", cw, syn_calc, data);
            end
        end
        $display("SCRATCH DONE");
        $finish;
    end
