module tb;
    reg clk = 0, rst_n = 1;
    reg [7:0] src = 0;
    reg we = 0, ack = 0;
    reg [1:0] addr = 0;
    reg [7:0] wdata = 0;
    reg [2:0] ack_id = 0;
    wire [7:0] pending;
    wire irq;
    wire [2:0] irq_id;
    integer errors = 0;

    int_ctrl dut (.clk(clk), .rst_n(rst_n), .src(src), .we(we), .addr(addr), .wdata(wdata),
                  .ack(ack), .ack_id(ack_id), .pending(pending), .irq(irq), .irq_id(irq_id));
    always #5 clk = ~clk;

    task check(input [7:0] p, input i, input [2:0] id);
        if (pending !== p || irq !== i || (i && irq_id !== id)) begin
            $display("FAIL: t=%0t pending=%h irq=%b irq_id=%0d expected pending=%h irq=%b irq_id=%0d",
                     $time, pending, irq, irq_id, p, i, id);
            errors = errors + 1;
        end
    endtask

    task write_reg(input [1:0] a, input [7:0] d);
        begin
            @(negedge clk); we = 1; addr = a; wdata = d;
            @(negedge clk); we = 0;
        end
    endtask

    initial begin
        #1 rst_n = 0;
        #11 rst_n = 1;
        write_reg(2'd1, 8'h00); // all level
        write_reg(2'd0, 8'hFF); // all enabled
        // lowest index should win priority: sources 2 and 5 both high (level)
        src = 8'h24; #1 check(8'h24, 1, 2);
        src = 8'h00; #1 check(8'h00, 0, 0);
        // edge mode source 2; rise and ack same cycle -> stays pending (rise wins)
        write_reg(2'd1, 8'h04); // source 2 edge
        @(negedge clk); src = 8'h04; ack = 1; ack_id = 3'd2;
        @(negedge clk); src = 8'h00; ack = 0; #1 check(8'h04, 1, 2);
        if (errors == 0) $display("SCRATCH TEST PASSED");
        else $display("SCRATCH TEST FAILED: %0d errors", errors);
        $finish;
    end
endmodule

module int_ctrl (
    input  wire       clk,
    input  wire       rst_n,
    input  wire [7:0] src,
    input  wire       we,
    input  wire [1:0] addr,
    input  wire [7:0] wdata,
    input  wire       ack,
    input  wire [2:0] ack_id,
    output wire [7:0] pending,
    output wire       irq,
    output reg  [2:0] irq_id
);
    localparam ADDR_MASK = 2'd0;
    localparam ADDR_MODE = 2'd1;

    reg  [7:0] mask;
    reg  [7:0] mode;
    reg  [7:0] src_q;
    reg  [7:0] edge_pend;
    integer    i;
    integer    j;

    wire [7:0] rise    = src & ~src_q;
    wire [7:0] ack_vec = ack ? (8'b0000_0001 << ack_id) : 8'b0000_0000;
    wire [7:0] active;

    assign pending = (mode & edge_pend) | (~mode & src);
    assign active  = pending & mask;
    assign irq     = |active;

    always @(*) begin
        irq_id = 3'd0;
        for (i = 0; i < 8; i = i + 1)
            if (active[i])
                irq_id = i;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mask <= 8'h00;
            mode <= 8'h00;
        end else if (we) begin
            case (addr)
                ADDR_MASK: mask <= wdata;
                ADDR_MODE: mode <= wdata;
                default:   ;
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            src_q <= 8'h00;
        else
            src_q <= src;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            edge_pend <= 8'h00;
        end else begin
            for (j = 0; j < 8; j = j + 1) begin
                if (ack_vec[j])
                    edge_pend[j] <= 1'b0;
                else if (mode[j] && rise[j])
                    edge_pend[j] <= 1'b1;
            end
        end
    end
endmodule

