module mult_seq (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        start,
    input  wire [7:0]  a,
    input  wire [7:0]  b,
    output reg         busy,
    output reg         done,
    output reg  [15:0] product
);
    // Shift-add signed multiplier: {acc, q} is the partial product register.
    // Each step adds the multiplicand to acc when q[0] is set (subtracts it on the
    // final, sign-bit step), then shifts {acc, q} right arithmetically by one.
    reg  [7:0] mcand;
    reg  [7:0] acc;
    reg  [7:0] q;
    reg  [2:0] cnt;

    wire       last   = (cnt == 3'd7);
    wire [8:0] m_ext  = {mcand[7], mcand};
    wire [7:0] m_neg  = -mcand;
    wire [8:0] addend = !q[0] ? 9'd0 : (last ? {m_neg[7], m_neg} : m_ext);
    wire [8:0] sum    = {acc[7], acc} + addend;

    wire [7:0] acc_nx = sum[8:1];
    wire [7:0] q_nx   = {sum[0], q[7:1]};

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mcand   <= 8'd0;
            acc     <= 8'd0;
            q       <= 8'd0;
            cnt     <= 3'd0;
            busy    <= 1'b0;
            done    <= 1'b0;
            product <= 16'd0;
        end else begin
            if (start) begin
                done  <= 1'b0;
                mcand <= a;
                q     <= b;
                acc   <= 8'd0;
                cnt   <= 3'd0;
                busy  <= 1'b1;
            end else if (busy) begin
                acc <= acc_nx;
                q   <= q_nx;
                cnt <= cnt + 3'd1;
                if (last) begin
                    busy    <= 1'b0;
                    done    <= 1'b1;
                    product <= {acc_nx, q_nx};
                end
            end
        end
    end
endmodule

`timescale 1ns/1ps
module tb;
    reg clk = 0, rst_n = 1;
    reg start = 0;
    reg [7:0] a = 0, b = 0;
    wire busy, done;
    wire [15:0] product;
    integer errors = 0, n;

    mult_seq dut (.clk(clk), .rst_n(rst_n), .start(start), .a(a), .b(b),
                  .busy(busy), .done(done), .product(product));
    always #5 clk = ~clk;
    initial begin #100000 $display("ERROR: watchdog timeout"); $finish; end

    task run(input signed [7:0] x, input signed [7:0] y);
        reg signed [15:0] exp;
        begin
            exp = x * y;
            @(negedge clk); start = 1; a = x; b = y;
            @(negedge clk); start = 0;
            if (busy !== 1'b1) begin $display("FAIL: busy not set after start"); errors = errors + 1; end
            n = 0;
            while (done !== 1'b1 && n < 20) begin @(negedge clk); n = n + 1; end
            if (done !== 1'b1 || n != 8) begin
                $display("FAIL: done after %0d cycles (expected 8)", n); errors = errors + 1;
            end
            if (busy !== 1'b0) begin $display("FAIL: busy still high at done"); errors = errors + 1; end
            if (product !== exp) begin
                $display("FAIL: %0d * %0d = %0d, expected %0d", x, y, $signed(product), exp);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        #1 rst_n = 0;
        #11 rst_n = 1;
        if (busy !== 1'b0 || done !== 1'b0 || product !== 16'd0) begin
            $display("FAIL: bad state after reset"); errors = errors + 1;
        end
        run(3, 5);
        run(12, 11);
        run(-6, 4);
        run(7, -2);
        run(-9, -9);
        run(0, 25);
        if (errors == 0) $display("TEST PASSED");
        else $display("TEST FAILED: %0d errors", errors);
        $finish;
    end
endmodule

