        // single requester always wins
        req = 4'b0100;
        for (i = 0; i < 3; i = i + 1) begin
            #1 expect_grant(4'b0100);
            @(negedge clk);
        end
        req = 4'b0000; #1 expect_grant(4'b0000);
        if (errors == 0) $display("TEST PASSED");
        else $display("TEST FAILED: %0d errors", errors);
        $finish;
    end
