module sat_adder (
    input  wire [7:0] a,
    input  wire [7:0] b,
    input  wire       sub,
    output wire [7:0] y,
    output wire       sat
);
    wire [7:0] b_eff = sub ? (~b + 8'd1) : b;
    wire [7:0] sum   = a + b_eff;
