        wr_en = 0;
        expect_flags(8, 1, 0);
        // drain completely, checking order
        for (i = 0; i < 8; i = i + 1) begin
            rd_en = 1;
            @(negedge clk);
            if (dout !== 8'h10 + i) begin
                $display("FAIL: read %0d dout=%h expected=%h", i, dout, 8'h10 + i);
                errors = errors + 1;
            end
