        wr_en = 0;
        expect_flags(3, 0, 0);
        for (i = 0; i < 3; i = i + 1) begin
            rd_en = 1;
            @(negedge clk);
            if (dout !== 8'hA0 + i) begin
                $display("FAIL: read dout=%h expected=%h", dout, 8'hA0 + i);
                errors = errors + 1;
            end
        end
        rd_en = 0;
        expect_flags(0, 0, 1);
        if (errors == 0) $display("TEST PASSED");
        else $display("TEST FAILED: %0d errors", errors);
        $finish;
    end
